import{_ as a,c as o,ae as t,o as s}from"./chunks/framework.Buicxtqr.js";const p=JSON.parse('{"title":"BuddyGenAI Database Info","description":"","frontmatter":{},"headers":[],"relativePath":"dev/database-info.md","filePath":"dev/database-info.md"}'),i={name:"dev/database-info.md"};function n(r,e,d,l,c,u){return s(),o("div",null,e[0]||(e[0]=[t('<h1 id="buddygenai-database-info" tabindex="-1">BuddyGenAI Database Info <a class="header-anchor" href="#buddygenai-database-info" aria-label="Permalink to &quot;BuddyGenAI Database Info&quot;">​</a></h1><p>This is meant to explain how BGAI uses and handles a database across its versions.</p><h2 id="electron-version" tabindex="-1">Electron version <a class="header-anchor" href="#electron-version" aria-label="Permalink to &quot;Electron version&quot;">​</a></h2><blockquote><p><code>main</code> branch</p><p>Code found at <code>/migrations/*</code>, <code>/electron/modules/db.ts</code>, <code>/src/lib/sql.ts</code> and <code>/src/lib/api/*</code>.</p></blockquote><ul><li>uses SQLite via <a href="https://www.npmjs.com/package/better-sqlite3" target="_blank" rel="noreferrer">better-sqlite3</a></li><li>Schema @ <code>/migrations/*.sql</code></li><li>IPC methods are exposed (in <code>/electron/modules/db.ts</code>) and used (in <code>/src/composables/useElectron.ts</code>) to run SQL (parameterized) queries constructed by the renderer process.</li><li>Helper methods in <code>/src/lib/sql.ts</code> are used in <code>/src/lib/api/*</code> files to avoid writing statements directly.</li></ul><h2 id="single-page-app-version" tabindex="-1">Single Page App version <a class="header-anchor" href="#single-page-app-version" aria-label="Permalink to &quot;Single Page App version&quot;">​</a></h2><blockquote><p><code>spa-version</code> branch</p><p>Code found at <code>/src/lib/db/schema.ts</code>, <code>/src/lib/sql.ts</code> and <code>/src/lib/api/*</code>.</p></blockquote><ul><li>uses IndexedDB via <a href="https://dexie.org/" target="_blank" rel="noreferrer">Dexie.js</a></li><li>Schema @ <code>/src/lib/db/schema.ts</code></li><li>DB is queried in <code>/src/lib/api/*</code> files, with rewritten helper methods in <code>/src/lib/sql.ts</code> to construct equivalent Dexie statements/queries from the same arguments.</li><li>The <code>useElectron</code> methods are modified to query Dexie directly and return the results.</li></ul><h2 id="eventual-goal" tabindex="-1">Eventual Goal <a class="header-anchor" href="#eventual-goal" aria-label="Permalink to &quot;Eventual Goal&quot;">​</a></h2><p>After some thinking, I think what I want to do overall is use Dexie for all versions and simply have different behavior for different versions:</p><ul><li><strong>SPA</strong> remains the same.</li><li><strong>Electron</strong> version would use the same code as the SPA, and would save/load to file(s) when data changes and on app start.</li><li><strong>Server</strong> version could maintain a single (or multiple) set of DB files which would be used to hydrate a client&#39;s IndexedDB on load. I&#39;m thinking that there would be controls for syncing to the server, essentially allowing you to use the app in SPA mode despite connecting to a Server instance.</li></ul>',11)]))}const b=a(i,[["render",n]]);export{p as __pageData,b as default};
